-- 07_indexes/02_foreign_keys.sql
-- Declared foreign keys (added AFTER loading so the bulk load is fast). They are the physical proof of referential integrity:
-- the load fails if any fact row points to a missing dimension row. Names follow the pattern fk_<table>_<column>.

